import { useState } from "react";
import { Button, Card, Disclosure, PageHeader, StatusPill, Typography } from "@autograph/components";
import { RecordDetailPanel } from "@autograph/compositions";

const money = (value: number) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(value);

export default function CompensationReview() {
  const [recommendation, setRecommendation] = useState<"none" | "recommended" | "held">("none");
  const base = 152000;
  const bonus = 22800;
  const benefits = 18000;
  const employerTax = Math.round(base * 0.0765);
  const packageCost = base + bonus + benefits + employerTax;
  const plannedBase = Math.round(base * 1.09);
  const midpoint = 145000;
  const midpointDelta = base - midpoint;
  const plannedMidpointDelta = plannedBase - midpoint;

  return (
    <main className="min-h-screen bg-[var(--color-bg-page)] px-[var(--space-6)] py-[var(--space-6)] text-[var(--color-text-primary)]">
      <div className="mx-auto grid w-full max-w-[1180px] gap-[var(--space-6)]">
        <PageHeader
          title="Compensation planning review"
          subtitle="Review Taylor Nguyen’s synthetic draft for the FY27 planning window. Figures are explanatory estimates only."
          actions={<StatusPill label="Draft" tone="neutral" detail="CMP-29" />}
        />

        {recommendation !== "none" ? (
          <Card className={recommendation === "recommended" ? "border-[var(--color-action-primary)]" : undefined}>
            <div role="status" className="flex flex-wrap items-center justify-between gap-[var(--space-3)]">
              <div>
                <Typography variant="body-strong">{recommendation === "recommended" ? "Planning recommendation recorded in this preview" : "Draft kept for further review"}</Typography>
                <Typography tone="secondary" className="mt-[var(--space-1)] mb-0">This simulation does not change the proposal, contact an approver, or write to payroll.</Typography>
              </div>
              <Button size="sm" intent="secondary" onClick={() => setRecommendation("none")}>Clear simulation</Button>
            </div>
          </Card>
        ) : null}

        <section aria-label="Decision summary" className="grid gap-[var(--space-4)] lg:grid-cols-3">
          <Card title="Annual package estimate">
            <Typography variant="section-title" className="m-0">{money(packageCost)}</Typography>
            <Typography tone="secondary" className="mt-[var(--space-1)] mb-0">Base, target bonus, annual benefits, and estimated employer tax.</Typography>
          </Card>
          <Card title="Current base vs. L5 midpoint">
            <Typography variant="section-title" className="m-0">{money(midpointDelta)} above</Typography>
            <Typography tone="secondary" className="mt-[var(--space-1)] mb-0">4.8% above the {money(midpoint)} midpoint before the planned increase.</Typography>
          </Card>
          <Card title="Planned base at +9%">
            <Typography variant="section-title" className="m-0">{money(plannedBase)}</Typography>
            <Typography tone="secondary" className="mt-[var(--space-1)] mb-0">{money(plannedMidpointDelta)} above midpoint (14.3%) if applied to current base.</Typography>
          </Card>
        </section>

        <section className="grid min-w-0 gap-[var(--space-6)] lg:grid-cols-[minmax(0,1fr)_360px]">
          <RecordDetailPanel
            title="Taylor Nguyen"
            subtitle="US • Level L5"
            status={{ label: "Draft", tone: "neutral", detail: "Planning only" }}
            metadata={[{ id: "proposal", label: "Proposal", value: "CMP-29" }, { id: "window", label: "Review window", value: "FY27 planning" }]}
            labelEmphasis="primary"
            sections={[
              { id: "package", title: "Package", collapsible: false, items: [
                { type: "field", id: "base", label: "Base salary", value: money(base) },
                { type: "field", id: "bonus", label: "Target bonus", value: `${money(bonus)} (15.0% of base)` },
                { type: "field", id: "benefits", label: "Annual benefits", value: money(benefits) },
                { type: "field", id: "tax", label: "Estimated employer tax", value: `${money(employerTax)} at 7.65%` },
                { type: "field", id: "total", label: "Estimated package cost", value: money(packageCost) }
              ]},
              { id: "comparison", title: "Band comparison", collapsible: false, items: [
                { type: "field", id: "band", label: "Band", value: "L5" },
                { type: "field", id: "midpoint", label: "Band midpoint", value: money(midpoint) },
                { type: "field", id: "current-position", label: "Current position", value: `${money(base)} • 104.8% of midpoint` },
                { type: "field", id: "planned-position", label: "At planned increase", value: `${money(plannedBase)} • 114.3% of midpoint` },
                { type: "note", id: "comparison-note", tone: "warning", title: "Decision evidence", body: "The planned base would sit $20,680 above the supplied midpoint. Confirm the applicable band policy before advancing the proposal." }
              ]}
            ]}
          />

          <aside className="grid content-start gap-[var(--space-4)]">
            <Card title="Next decision">
              <Typography variant="body-strong" className="m-0">Is this draft suitable to carry into the plan?</Typography>
              <Typography tone="secondary" className="mt-[var(--space-2)] mb-0">Base is already above midpoint, and the supplied 9% increase widens that difference.</Typography>
              <div className="mt-[var(--space-4)] grid gap-[var(--space-2)]">
                <Button intent="primary-strong" onClick={() => setRecommendation("recommended")}>Recommend for planning</Button>
                <Button intent="secondary" onClick={() => setRecommendation("held")}>Keep draft for review</Button>
              </div>
              <Typography variant="caption" tone="muted" className="mt-[var(--space-3)] mb-0">Both choices are temporary preview state. No approval or payroll workflow is represented.</Typography>
            </Card>

            <Card title="Policy assumptions">
              <Disclosure
                defaultOpen
                summary={<Typography as="span" variant="body-strong">How estimates are interpreted</Typography>}
                summaryClassName="py-[var(--space-1)]"
              >
                <div className="mt-[var(--space-3)] grid gap-[var(--space-2)]">
                  <Typography tone="secondary" className="m-0">• The 9% planned increase applies to current base salary only.</Typography>
                  <Typography tone="secondary" className="m-0">• Employer tax is estimated as 7.65% of base salary only.</Typography>
                  <Typography tone="secondary" className="m-0">• Bonus and benefits remain unchanged in the package estimate.</Typography>
                  <Typography tone="secondary" className="m-0">• The L5 midpoint is a comparison point, not a policy limit.</Typography>
                </div>
              </Disclosure>
            </Card>
          </aside>
        </section>
      </div>
    </main>
  );
}
